import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 depositAmt, uint256 cashOutAmt, address actor) public {
        vm.assume(actor != address(this));
        vm.assume(depositAmt >= 1 ether);
        vm.assume(cashOutAmt <= depositAmt);

        // Deposit
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.Deposit{value: depositAmt}();

        // CashOut
        vm.prank(actor);
        try c.CashOut(cashOutAmt) {
        } catch {}

        // Sum of all possible balances (only actor and address(0) receive deposits)
        uint256 totalBalances = c.balances(actor) + c.balances(address(0));
        uint256 contractBal = address(c).balance;

        // Invariant: sum of all balances equals contract ether balance
        assertTrue(totalBalances == contractBal);
    }
}

