pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmt, uint256 cashAmt, address user, uint256 seed) public {
        vm.assume(depositAmt >= c.MinDeposit());
        vm.assume(cashAmt <= depositAmt);
        vm.assume(user != address(0));
        vm.assume(user != address(this));
        vm.assume(user != address(c));
        vm.deal(user, depositAmt);
        vm.prank(user);
        c.Deposit{value: depositAmt}();
        // make a successful CashOut call (the counterparty is a normal EOA, so call succeeds)
        vm.prank(user);
        c.CashOut(cashAmt);
        // The invariant: after Deposit and CashOut, the user's balance must be depositAmt - cashAmt
        uint256 expected = depositAmt - cashAmt;
        uint256 actual = c.balances(user);
        assertTrue(actual == expected, "balance mismatch");
    }
}

